import{_ as l,o as i,c as t,j as e,a as n,a3 as s}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/berufskolleg/schueler-bk-abschluss-leistungsdaten-holen.png",u="/bilder/berufskolleg/schueler-bk-abschluss-pruefiung-teilleistungen.png",h="/bilder/berufskolleg/schueler-bk-abschluss-teilleistungen-alle.png",d="/bilder/berufskolleg/schueler-bk-abschluss-abschluss-berechnen.png",c="/bilder/berufskolleg/schueler-bk-abschluss-variables-feld.png",o="/bilder/berufskolleg/schueler-bk-abschluss-akt-abschnitt-ergebnis.png",w=JSON.parse('{"title":"Abschlüsse am Berufskolleg berechnen und prüfen","description":"","frontmatter":{"title":"Abschlüsse am Berufskolleg berechnen und prüfen","source_pageid":1278,"source_revision":4782},"headers":[],"relativePath":"zeugnisse/berufskolleg/bk-abschluss-schueler.md","filePath":"zeugnisse/berufskolleg/bk-abschluss-schueler.md"}'),g={name:"zeugnisse/berufskolleg/bk-abschluss-schueler.md"};function b(f,r,m,p,k,A){return i(),t("div",null,[...r[0]||(r[0]=[e("h1",{id:"abschlusse-am-berufskolleg-berechnen-und-prufen",tabindex:"-1"},[n("Abschlüsse am Berufskolleg berechnen und prüfen "),e("a",{class:"header-anchor",href:"#abschlusse-am-berufskolleg-berechnen-und-prufen","aria-label":'Permalink to "Abschlüsse am Berufskolleg berechnen und prüfen"'},"​")],-1),e("p",null,"Bearbeiten Sie Leistungsdaten, Prüfungsnoten und Abschlussberechnung für den gewählten Bildungsgang. Das berufliche Gymnasium verwendet die gesonderten Abitur- beziehungsweise FHR-Verfahren.",-1),e("p",null,[n("Am BK werden viele Abschlüsse vergeben. Über den Reiter "),e("em",null,"Schüler ➜"),n(),e("strong",null,"BK-Abschluss"),n(" können diese berechnet werden.")],-1),e("p",null,"Noch viel mehr als bei anderen Schulformen gilt, dass das Ergebnis von der ausgewählten Schülergruppe abhängt und die Berechnung nur für Schülergruppen durchgeführt wird, bei denen die Abschlussberechnung sinnvoll ist.",-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Am beruflichen Gymnasium ist für den schulischen Teil der Fachhochschulreife der Reiter "),e("strong",null,"Schüler ➜ FHR"),n(" vorgesehen. Der Erwerb ist frühestens "),e("strong",null,"nach dem ersten Jahr der Qualifikationsphase"),n(" möglich; siehe "),e("a",{href:"https://bass.schule.nrw/Inhalt/6911.htm",target:"_blank",rel:"noreferrer"},"Praktikum-Ausbildungsordnung, Abschnitt IV"),n(". Die Leistungsbedingungen sind zusätzlich zu prüfen.")]),e("p",null,[n("Wird die "),e("em",null,"Allgemeine Hochschulreife"),n(" angestrebt, läuft die Berechnung analog zum Abitur über den Reiter "),e("em",null,"Schüler ➜ Abitur"),n(".")]),e("p",null,"Die anderen Abschlussberechnungen, auch von der vollen Fachhochschulreife, finden über den Reiter BK-Abschluss statt.")],-1),s('<p>Bei der Berechnung des Abschlusses greift SchILD-NRW auf die beim Schüler eingetragene <em>Prüfungsordnung</em> und gegebenenfalls auf den <em>Jahrgang</em> zurück, um die jeweiligen Kriterien zu prüfen.</p><h2 id="leistungsdaten-holen" tabindex="-1">Leistungsdaten holen <a class="header-anchor" href="#leistungsdaten-holen" aria-label="Permalink to &quot;Leistungsdaten holen&quot;">​</a></h2><p><a href="/bilder/berufskolleg/schueler-bk-abschluss-leistungsdaten-holen.png"><img src="'+a+'" alt="Die Berechnung der Abschlüsse am BK beginnt damit, die Leistungsdaten aus dem aktuellen Lernabschnitt in diesen Reiter zu holen." loading="lazy"></a></p><p><em>Die Berechnung der Abschlüsse am BK beginnt damit, die Leistungsdaten aus dem aktuellen Lernabschnitt in diesen Reiter zu holen.</em></p><p>Klicken Sie im Reiter <strong>BK-Abschluss</strong> auf <code>Leistungsdaten holen</code>.</p><p>Es werden die Leistungsdaten, also Fach, Fachlehrkraft und die Note als Vornote aus dem aktuellen Lernabschnitt im Reiter <em>BK-Abschluss</em> eingetragen.</p>',6),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,[n("Hierbei ist zu beachten, ob Prüfungsordnungen vorsehen, dass die Vornote eine "),e("em",null,"Ganzjahresnote"),n(" ist. Die Note, die geholt wird, ist die des letzten Halbjahres. Wird die Vornote sinnvoll über eine Teilleistung erfasst, müssen die geholten Noten noch mit der Teilleistungs-Vornote überschrieben werden.")])],-1),s('<h2 id="teilleistungen-und-prufungsnoten" tabindex="-1">Teilleistungen und Prüfungsnoten <a class="header-anchor" href="#teilleistungen-und-prufungsnoten" aria-label="Permalink to &quot;Teilleistungen und Prüfungsnoten&quot;">​</a></h2><p><a href="/bilder/berufskolleg/schueler-bk-abschluss-pruefiung-teilleistungen.png"><img src="'+u+'" alt="Holen Sie bei einer eventuellen Prüfung die Prüfungsnote aus einer Teilleistung." loading="lazy"></a></p><p><em>Holen Sie bei einer eventuellen Prüfung die Prüfungsnote aus einer Teilleistung.</em></p><p>Wird eine Prüfung abgelegt, können Sie diese in einer <em>Teilleistung</em> hinterlegen.</p><p>Um diese Note in den Reiter <em>BK-Abschluss</em> zu holen, klicken Sie auf <code>Note aus Teilleistungen holen</code>. Hier ist dann anzuwählen, ob es sich bei der <strong>Notenart</strong> um eine <em>schriftliche</em> oder <em>mündliche</em> Note handelt.</p><h2 id="zulassung-berechnen" tabindex="-1">Zulassung berechnen <a class="header-anchor" href="#zulassung-berechnen" aria-label="Permalink to &quot;Zulassung berechnen&quot;">​</a></h2><p>Liegt nach der Prüfungsordnung eine Prüfung an, kann durch einen Klick auf <code>Zulassung prüfen</code> links unter <em>Zulassung</em> das Feld <strong>Prüfung</strong> auf <em>Ja</em> oder <em>Nein</em> gesetzt werden.</p>',7),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,[n("Hier ist Bk-typisch vom Anwender auf die konkrete Gliederung und den Abschluss des Schülers zu achten: Bei "),e("em",null,"A01"),n(", der normalen Berufsschule, gibt es keine "),e("em",null,"Zulassung"),n(", daher wäre die Schalfläche hier natürlich auch nicht zu verwenden.")])],-1),s('<p><a href="/bilder/berufskolleg/schueler-bk-abschluss-teilleistungen-alle.png"><img src="'+h+'" alt="Wählen Sie über die Notenart, welche Spalte im Reiter BK-Abschluss mit der dann folgend ausgewählten zugehörigen Teilleistung befüllt werden soll." loading="lazy"></a></p><p><em>Wählen Sie über die <strong>Notenart</strong>, welche Spalte im Reiter BK-Abschluss mit der dann folgend ausgewählten <strong>zugehörigen Teilleistung</strong> befüllt werden soll.</em></p><p>Beim Holen von Noten aus Teilleistungen wählen Sie unter <strong>zugehörige Teilleistung</strong> den Eintrag aus, der die gewünschte Note enthält.</p><p>An dieser Stelle werden zum Beispiel die geholten <em>Halbjahresnoten</em> mit der tatsächlichen <em>Vornote</em> überschrieben.</p><p>Die Einträge <em>schriftliche Note</em> und <em>mündliche Note</em> beziehen sich hier auf die entsprechenden Prüfungsnoten.</p><h2 id="mundliche-prufungen-festlegen" tabindex="-1">Mündliche Prüfungen festlegen <a class="header-anchor" href="#mundliche-prufungen-festlegen" aria-label="Permalink to &quot;Mündliche Prüfungen festlegen&quot;">​</a></h2><p>Über die Haken bei <strong>Mdl. Prüfung</strong> und <strong>Mdl. freiw. Prüfung</strong> können aufgrund der Prüfungsleistung - nach der jeweiligen Prüfungsordnung vorgesehene - notwendige Bestehensprüfungen oder erlaubte freiwillige Prüfungen gesetzt werden.</p><p>Der Schalter <code>Mündliche Prüfungen festlegen</code> setzt bei Bedarf den Haken bei <strong>Mdl. Prüfung</strong>.</p><p>Der Haken bei der <strong>Mdl. Prüfung</strong> kann auch per Gruppenprozess durch eine Prüfung der erbrachten Leistungen für eine Schülergruppe geprüft und gesetzt werden.</p><h2 id="abschluss-berechnen" tabindex="-1">Abschluss berechnen <a class="header-anchor" href="#abschluss-berechnen" aria-label="Permalink to &quot;Abschluss berechnen&quot;">​</a></h2><p><a href="/bilder/berufskolleg/schueler-bk-abschluss-abschluss-berechnen.png"><img src="'+d+'" alt="Berechnung des Abschlusses basierend auf den Abschlussnoten." loading="lazy"></a></p><p><em><strong>Berechnung des Abschlusses</strong> basierend auf den Abschlussnoten.</em></p><p>Wurden die Abschlussnoten eingetragen, lässt sich mit einem Klick auf <code>Abschluss berechnen</code> die Abschlussberechnung nach Prüfungsordnung und Jahrgang anstoßen.</p><p>Unter Umständen kann die Prüfung auch vom zuvor <em>&quot;höchsten bisher erreichten Abschluss&quot;</em> abhängen.</p><p>Im Bereich <strong>Abschluss</strong> wird angezeigt, welche schulischen oder beruflichen Abschlüsse erreicht wurden.</p><p>Bei Zutreffen der Kriterien für den Bildungsgang wird hier im Protokoll eine eventuelle FHR-Note oder ähnlich angezeigt.</p><p><a href="/bilder/berufskolleg/schueler-bk-abschluss-variables-feld.png"><img src="'+c+'" alt="Das Feld links der Leistungsdaten kann je nach Bildungsgang viele Formen annehmen." loading="lazy"></a></p><p><em>Das Feld links der Leistungsdaten kann je nach Bildungsgang viele Formen annehmen.</em></p><p>Je nach Bildungsgang kann das Feld links der Leistungsdaten viele Formen annehmen und Zulassungen, Prüfungen, schulische und berufliche Abschlüsse und weitere Daten in unterschiedlicher Form und Ausführlichkeit enthalten.</p><p>Die in dieser Dokumentation abgebildeten Varianten können als Beispiele angesehen werden.</p><p><a href="/bilder/berufskolleg/schueler-bk-abschluss-akt-abschnitt-ergebnis.png"><img src="'+o+'" alt="Das Ergebnis der Abschlussberechnung unter Schüler ➜ Akt. Abschnitt." loading="lazy"></a></p><p><em>Das Ergebnis der Abschlussberechnung unter Schüler ➜ Akt. Abschnitt.</em></p><p>Die Abschlüsse finden Sie dann auch unter <em>Aktueller Abschnitt ➜ Zeugnis/Abschluss</em>.</p><h2 id="abschlussnoten-in-leistungsdaten-ubertragen" tabindex="-1">Abschlussnoten in Leistungsdaten übertragen <a class="header-anchor" href="#abschlussnoten-in-leistungsdaten-ubertragen" aria-label="Permalink to &quot;Abschlussnoten in Leistungsdaten übertragen&quot;">​</a></h2><p>Haben Sie alle Leistungsdaten im Reiter hinterlegt und die <strong>Abschlussnoten</strong> erfasst, klicken Sie auf <code>Abschlussnoten in Leistungsdaten übertragen</code>. Hierüber werden die Noten aus diesem Reiter zurück in den Bereich <em>Note</em> des aktuellen Abschnitts geschrieben.</p><p>Hierbei wird die alte Halbjahresnote nun mit der Abschlussnote überschrieben.</p>',26),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Beachten Sie, dass die automatischen Werkzeuge als Unterstützung ohne Gewähr zu verstehen sind. Die Schule mit ihren jeweils Verantwortlichen trägt die Verantwortung für die Korrektheit im Rahmen der geltenden Prüfungsordnung aller Ergebnisse.")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=BK-Abschluss_(Sch%C3%BCler)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 4782.")],-1)])])}const v=l(g,[["render",b]]);export{w as __pageData,v as default};
